void Fabric::Send(uint64_t id, uint32_t src,uint32_t dst,uint64_t bytes,unsigned plane,Done done,Done received) {
  Require(src<gpus_ && dst<gpus_ && src!=dst && bytes>0 && bytes<=64*1024*1024 && plane<planes_,"invalid message");
  Require(reachable_[(src*gpus_+dst)*planes_+plane] && reachable_[(dst*gpus_+src)*planes_+plane],"no data/ACK packet-switch path");
  Require(id<2147483648u && !flows_.count(id) && flows_.size()<MaxMessages(),"message identity/count budget exceeded");
  // Stable across counterfactual runs even if completion order changes.
  const uint16_t port=10000+id%50000;
  Flow flow;flow.done=std::move(done);flow.received=std::move(received);
  flow.src=src;flow.dst=dst;flow.plane=plane;flow.bytes=bytes;flow.port=port;flow.ready=Now();
  flows_.emplace(id,std::move(flow));
  if(topology_.contains("intra_host") && topology_.at("intra_host").at("enabled")==true &&
     topology_.at("nodes").at(src).at("server")==topology_.at("nodes").at(dst).at("server")) {
    SendLocal(id);return;
  }
  const auto key=std::make_tuple(Address(src,plane).Get(),Address(dst,plane).Get(),port);
  Require(port_to_flow_.emplace(key,id).second,"RDMA endpoint/port identity collision; change bounded identity layout");
  drivers_[src]->AddQueuePair(src,dst,id,bytes,3,Address(src,plane),Address(dst,plane),port,port,0,
      config_.at("base_rtt_ns"),MakeCallback(&Fabric::Noop),MakeCallback(&Fabric::Noop));
}

void Fabric::Acked(Ptr<RdmaQueuePair> qp) {
  auto& flow=flows_.at(qp->GetTag());
  Require(!flow.acked && qp->IsFinished(),"repeated or partial ACK completion");
  CheckReceived(qp->GetTag());
  Require(flow.data_ready,"ACK completion preceded receiver accepted all data");
  flow.acked=true;flow.ack=Now();
  flow.feedback=!qp->mlx.m_first_cnp;
  flow.rate_at_ack=qp->m_rate.GetBitRate();
  // RdmaHw deletes its send QP after this trace returns. Do not load the next
  // graph or submit new work inside that cleanup stack.
  if(flow.done)Simulator::ScheduleNow(flow.done);
}
void Fabric::CheckReceived(uint64_t id) {
  auto& f=flows_.at(id); if(f.data_ready)return;
  const uint16_t port=f.port;
  auto rx=drivers_[f.dst]->m_rdma->GetRxQp(Address(f.dst,f.plane).Get(),Address(f.src,f.plane).Get(),port,port,3,false);
  if(rx && rx->ReceiverNextExpectedSeq>=f.bytes) {
    f.data_ready=true;f.receive_ready=Now();
    if(f.received)Simulator::ScheduleNow(f.received);
  }

void Messages::Deliver(uint64_t id) {
  auto& op=operations_.at(id);
  if(op.received && op.posted && !op.recv_called) {
    op.recv_called=true;op.recv_callback=Now();
    auto callback=std::move(op.recv_done);callback();
  }
  if(op.acked && !op.send_called) {
    op.send_called=true;op.send_callback=Now();
    auto callback=std::move(op.send_done);callback();
  }
}
void Messages::Post(bool send,int rank,uint64_t bytes,int type,int peer,int tag,void(*callback)(void*),void* arg) {
  Require(type==AstraSim::UINT8 && callback,"ASTRA native messages must use byte counts and a callback");
  const auto key=send?std::make_tuple(rank,peer,tag):std::make_tuple(peer,rank,tag);
  Require(keys_.count(key),"unregistered ASTRA message");
  const auto id=keys_.at(key);auto& op=operations_.at(id);
  Require(bytes==op.bytes,"ASTRA count differs from descriptor");
  if(send) {
    Require(!op.sent,"SEND posted twice");op.sent=true;op.send_done=[callback,arg](){callback(arg);};
    op.send_post=Now();
    fabric_.Send(id,op.src,op.dst,bytes,op.plane,
      [this,id](){operations_.at(id).acked=true;Deliver(id);},
      [this,id](){operations_.at(id).received=true;Deliver(id);});
  } else {
    Require(!op.posted,"RECV posted twice");op.posted=true;op.recv_done=[callback,arg](){callback(arg);};
    op.recv_post=Now();
    ns3::Simulator::ScheduleNow([this,id](){Deliver(id);});

void Pump() {
  if(!std::all_of(boot_done_.begin(),boot_done_.end(),[](bool x){return x;}))return;
  Json completed=Json::array();
  for(auto it=waves_.begin();it!=waves_.end();) {
    auto& w=it->second;
    if(w.finished.size()!=w.ranks.size()) {++it;continue;}
    Require(messages_.Complete(w.messages),"graph finished before matched message callbacks");
    for(int rank:w.ranks) {
      Require(systems_[rank]->workload->can_load_graph(),"rank finished with live ASTRA resources");
      owners_[rank].clear();
    }
    completed.push_back({{"graph_id",it->first},{"finished_ns",Now()}});
    history_.push_back({{"graph_id",it->first},{"start_ns",w.start},{"finished_ns",Now()},{"rank_ids",w.ranks}});
    it=waves_.erase(it);
  }
  // Partial rank completions do not make an EP group schedulable. Suppress
  // empty control round trips, preserving the initial decision and all
  // actual group completions in this finite, no-new-arrivals service.
  if(completed.empty() && decision_>0)return;
  Json available=Json::array();
  for(unsigned r=0;r<owners_.size();++r)if(owners_[r].empty())available.push_back(r);
  Json request={{"type","DECIDE"},{"decision_id",decision_},{"now_ns",Now()},
                {"completed",completed},{"available_rank_ids",available}};
  std::cout<<"MOE_RDMA_EVENT "<<request.dump()<<std::endl;
  std::string line;Require(bool(std::getline(std::cin,line)) && line.size()<=1048576,"frontend EOF or oversized commit");
  auto commit=Json::parse(line);
  Require(commit.at("type")=="COMMIT" && commit.at("decision_id")==decision_ && commit.at("now_ns")==Now(),
          "frontend commit identity/time mismatch");
  ++decision_;Require(decision_<=4096,"service decision budget exceeded");
  const auto& submissions=commit.at("submissions");
  if(commit.at("service_finished")==true) {
    Require(submissions.empty() && waves_.empty() && fabric_.Drained(),"premature service termination");
    finished_=true;ns3::Simulator::Stop();return;
  }
  Require(!submissions.empty() || !waves_.empty(),"frontend and network made no progress");

void Fabric::SendLocal(uint64_t id) {
  auto& flow=flows_.at(id);const auto local=topology_.at("intra_host");
  const uint64_t rate=local.at("rate_bps"),chunk=local.at("chunk_bytes");
  const int64_t delay=local.at("delay_ns");
  Require(local.at("kind")=="nonblocking_chunked_crossbar" && rate>0 && chunk>0,"invalid local fabric");
  flow.local=true;
  const unsigned src=flow.src,dst=flow.dst;
  const auto reserve=[this,rate](unsigned gpu,bool ingress,int64_t arrival,uint64_t size){
    auto key=std::make_pair(gpu,ingress);
    const int64_t start=std::max(arrival,local_free_[key]);
    const int64_t duration=(size*8000000000ull+rate-1)/rate;
    local_free_[key]=start+duration;
    if(!local_links_.count(key))local_links_[key]={{"gpu",gpu},{"direction",ingress?"to_switch":"from_switch"},
      {"server",topology_.at("nodes").at(gpu).at("server")},{"rate_bps",rate},{"payload_bytes",0ull},
      {"busy_ns",0ull},{"max_wait_ns",0ull},{"chunks",0ull}};
    auto& link=local_links_.at(key);
    link["payload_bytes"]=link.at("payload_bytes").get<uint64_t>()+size;
    link["busy_ns"]=link.at("busy_ns").get<uint64_t>()+duration;
    link["chunks"]=link.at("chunks").get<uint64_t>()+1;
    link["max_wait_ns"]=std::max(link.at("max_wait_ns").get<uint64_t>(),static_cast<uint64_t>(start-arrival));
    return std::make_pair(start,start+duration);
  };
  for(uint64_t offset=0;offset<flow.bytes;offset+=chunk) {
    const auto size=std::min(chunk,flow.bytes-offset);const auto interval=reserve(src,true,Now(),size);
    Simulator::Schedule(NanoSeconds(interval.first-Now()),[this,id,size,offset,interval](){
      auto& f=flows_.at(id);
      if(f.first_tx<0)f.first_tx=Now();
      f.payload+=size;++f.chunks;
      if(offset==0) {f.ingress_start=interval.first;f.ingress_end=interval.second;}
    });
    Simulator::Schedule(NanoSeconds(interval.second+delay-Now()),[this,id,dst,size,offset,delay,reserve](){
      const auto output=reserve(dst,false,Now(),size);
      if(offset==0) {
        flows_.at(id).egress_start=output.first;
        flows_.at(id).egress_end=output.second;
      }
      Simulator::Schedule(NanoSeconds(output.second+delay-Now()),[this,id,size](){
        auto& f=flows_.at(id);f.received_bytes+=size;
        Require(f.received_bytes<=f.bytes,"local received bytes exceeded message");
        if(f.received_bytes==f.bytes) {
          f.data_ready=f.acked=true;f.receive_ready=f.ack=Now();
          if(f.received)Simulator::ScheduleNow(f.received);
          if(f.done)Simulator::ScheduleNow(f.done);
        }

// One current state per rank. No events, packet annotations or scheduler writes.
// Changes stream through the existing bounded store; same-time order is kept.
class SendStateRecords {

void Observe(int rank,uint64_t time,uint64_t ready,uint32_t active,uint32_t capacity) {
    auto& state=state_.at(rank);
    if(finished_ || time<state.time || time>end_ || active>capacity || (!capacity && ready) || ready>INT64_MAX)
        throw std::runtime_error("Invalid observed send state");
    if(!state.sequence && (time!=0 || ready || active || capacity))
        throw std::runtime_error("Send-state initial snapshot must precede slot configuration");
    const Values values{ready,active,capacity};
    if(state.sequence && state.values==values) return;
    Emit(rank,time,values,state.sequence?"update":"initial");

void Observe(ns3::Ptr<const ns3::UbLdstThread> thread,std::string event,
             ns3::Ptr<const ns3::UbLdstTaskSegment> segment,uint64_t offset,uint32_t bytes)
{
    const uint64_t now=ns3::Simulator::Now().GetNanoSeconds();
    if (now>policy_.at("end_ns").get<uint64_t>()) return;
    auto node=ns3::NodeList::GetNode(thread->GetNodeId());
    auto api=node->GetObject<ns3::UbController>()->GetUbFunction()->GetUbLdstApi();
    ns3::UintegerValue pool; api->GetAttribute("RequestIdCount",pool);
    Json queue=Json::array(),pending=Json::array();
    auto add=[&](auto& rows,Json item){
        if (queue.size()+pending.size()>=policy_.at("max_snapshot_items").get<uint64_t>())
            throw std::runtime_error("Native queue snapshot budget exceeded; no partial state");
        rows.push_back(std::move(item));
    };
    for (bool load:{false,true}) for (auto task:thread->GetQueueSnapshot(load)) add(queue,Task(task));
    for (const auto& request:api->GetRequestSnapshot()) {
        auto item=Task(request.segment);
        item["request_id"]=request.requestId;item["offset"]=request.offset;item["bytes"]=request.bytes;
        add(pending,std::move(item));
    }
    Json affected=Task(segment);
    if (!affected.is_null()) { affected["offset"]=offset;affected["bytes"]=bytes; }
    Json row={{"rank_id",rank_by_node_.at(thread->GetNodeId())},{"node_id",thread->GetNodeId()},
        {"store_queue_policy",thread->GetStoreQueuePolicy()},
        {"last_store_producer",thread->GetLastStoreProducer()?Json(*thread->GetLastStoreProducer()):Json(nullptr)},
        {"thread_id",thread->GetThreadId()},{"time_ns",now},{"event",event},{"affected",affected},
        {"store_inflight",thread->GetInFlight(false)},{"load_inflight",thread->GetInFlight(true)},
        {"store_capacity",thread->GetCapacity(false)},{"load_capacity",thread->GetCapacity(true)},
        {"request_pool_capacity",pool.Get()},{"queue",std::move(queue)},{"pending",std::move(pending)}};

void Fabric::TxTrace(Fabric* f,unsigned node,unsigned port,Ptr<const Packet> p) {
  auto& row=f->ports_.at(node).at(port); const auto h=Header(p); const uint64_t size=p->GetSize();
  row.wire+=size;
  if(h.l3Prot==0x11)row.data+=size;else row.control+=size;
  if(h.l3Prot!=0x11)return;
  ++row.packets;
  auto it=f->port_to_flow_.find({h.sip,h.dip,h.udp.sport}); if(it==f->port_to_flow_.end())return;
  auto& flow=f->flows_.at(it->second);
  if(node==flow.src) {
    if(flow.first_tx<0)flow.first_tx=Now();
    ++flow.packets;
    flow.payload+=size-h.GetSerializedSize();
  }
  if(h.udp.seq==0)flow.path.push_back({node,port,Now()});
}
void Fabric::RxTrace(Fabric* f,unsigned node,unsigned port,Ptr<const Packet> p) {
  auto h=Header(p);
  if(h.l3Prot==0x11 && h.GetIpv4EcnBits()==3) {
    ++f->ports_.at(node).at(port).ecn;
  }
  if(node>=f->gpus_ || h.l3Prot!=0x11)return;
  auto it=f->port_to_flow_.find({h.sip,h.dip,h.udp.sport});
  if(it!=f->port_to_flow_.end()) {
    const auto id=it->second;
    // MacRx fires before RdmaHw acceptance; inspect contiguous accepted bytes after it returns.
    Simulator::ScheduleNow([f,id](){f->CheckReceived(id);});
  }
}
void Fabric::QueueTrace(Fabric* f,unsigned node,unsigned port,Ptr<const Packet>,uint32_t) {
  if(node<f->gpus_)return;
  auto& row=f->ports_.at(node).at(port);
  const auto bytes=row.device->GetQueue()->GetNBytesTotal();
  row.max_queue=std::max(row.max_queue,bytes);
  ++f->queue_observations_;
  if(!f->config_.contains("limits") || f->config_.at("limits").at("queue_capture")=="events") {
    const auto maximum=f->config_.contains("limits")?f->config_.at("limits").at("max_queue_events").get<uint64_t>():200000;
    Require(f->queue_events_.size()<maximum,"passive queue event budget exceeded");
    f->queue_events_.push_back({static_cast<uint64_t>(Now()),node,port,bytes});
  }
